# 人工题型卡片。变式中的正则只负责关联已阅读证据，不生成知识结论。
CARDS = []
def add(id,module,pre,scope,method,pitfall,mastery,difficulty,variants):
 CARDS.append(dict(id=id,module=module,pre=pre,scope=scope,method=method,pitfall=pitfall,mastery=mastery,difficulty=difficulty,variants=variants))

add('DS01','算法与线性结构','求和、对数、循环边界','从代码或所设计算法求时间、辅助空间；区分平均与最坏。','先确定基本操作和输入规模，再求执行次数。独立嵌套才能相乘；相关上下界用求和。几何增长解不等式，递归计调用及栈深。顺序阶段取总和后保留主项。','把外层次数当作n；忽略标记数组初始化；把输出空间计入辅助空间；将快速选择平均线性写成最坏线性。','能写出次数式再化简；高分训练要求同时说明空间计量口径和最坏情形。','常规；较难处是非线性终止条件和设计算法后的摊合计数。',[
('循环次数与递推','循环|递归|双循环|倍增|平方|i²|sqrt','累加型解三角和，平方条件解平方根，倍增内层随i时用几何和；不要凭循环层数判断。'),
('算法时间空间界','算法|线性|扫描|指针|矩阵|顺序表|中位数|标记|邻接表|最坏|O[(]','以实际访问对象计数，分别列输入、输出、辅助数组和递归栈。')])
add('DS02','算法与线性结构','数组地址、顺序存储','按位访问、保序插删以及按号索引的结构选择。','地址=基址+下标×元素宽度。按位读取常数次；保序插入需后移后缀，删除需前移后缀；尾部无后缀可移动。','按位访问不等于按值查找；扩容和保序条件要按题限定。','能给出移动数n−i或n−i+1及边界；能解释中断向量为何适合数组索引。','基础；难点是操作语义及存储空间前提。',[('按位访问与保序移动','.*','根据给定的是位置、值还是索引号选择操作，不能把查找成本隐藏在插删外。')])
add('DS03','算法与线性结构','数组、不变量、单调性、极值','历年数组算法设计；不要求未考的通用算法专题。','先把目标写成数学条件，再选不变量或单调排除规则，最后给完整循环边界、返回值和复杂度证明。不同目标不能统称双指针后套同一模板。','多数候选未复核；中位数删错奇偶边界；忽略负数、零、重复和允许元素与自身相乘。','能闭卷写思想、代码、复杂度三部分，并用极端输入检查。高分要求解释每次排除为何不丢解。','综合；较难为双序列中位数和三元组距离的排除证明。',[
('原地循环移位','移位|逆置','逆置前p项、后n−p项，再逆置全部；说明p规范化和空区间。'),
('双有序表中位数','中位数|折半','比较两中位数，等量删去一表小端和另一表大端；奇偶长度决定保留哪个中点。'),
('多数投票','主元素|投票','不同元素配对抵消得到候选，再完整扫描验证次数严格超过n/2。'),
('平衡数量且最大和差','子集|半区|划分','选择第floor(n/2)位置，大小两组各取对应半区；不需要全排序。'),
('最小缺失正整数','缺失|标记','答案在1…n+1；仅记录1…n，忽略无关值，再找首个未出现位置。'),
('三有序数组距离','三元组|三指针|每指针','距离化为2(max−min)，只推进当前最小值对应指针，任一数组耗尽即结束。'),
('逐元素最大乘积','乘积|极值|输出数组|全负','先求全局最小和最大：正元素乘最大，负元素乘最小，零结果零；原题允许j=i。')])
add('DS04','算法与线性结构','指针、头结点、结点身份','链表结构操作、查找与原地重排；结点地址和数据值分开。','先画局部链接再改指针；需要旧后继时先保存，删除后再释放。设计题给循环不变量与空表、单结点、奇偶长度边界。','覆盖尚需使用的指针；把同值误认为同一结点；删除时前驱误前进；尾部未断链成环。','能无丢链无环完成操作并说明每个指针职责；高分训练用最小反例检查。','常规到综合；共享后缀和三阶段重排需要多个不变量。',[
('局部插删与循环链边界','插入|删除|删首|摘除|双链|双向|隔一|有序链表','改指针前保存旧关系；双链需双向维护，循环链单结点删除需同步首尾。'),
('倒数第k项','倒数|快慢|不足k|成功标志','快指针先走k步再同步；不足k返回失败，头结点不计数据元素。'),
('共同后缀','共享后缀|共同后缀|两链表','先求长度差并对齐，之后按地址比较；相同字符不充分。'),
('有界去重','去重|标记|重复结点|data/link','按绝对值映射标记数组，保留首次；标记初始化成本计入复杂度。'),
('合并与首尾重排','合并|重排|三阶段|奇偶长度','升序链转降序可头插；首尾交错用找中点、逆置后半、交替拼接，最后断链。')])
add('DS05','算法与线性结构','后进先出、递归调用','出栈合法性、限制条件计数、容量和递归栈。','按目标输出逐个压入尚未入栈元素，栈顶匹配才弹出，记录最大深度。计数须遵守题给首项或连续弹出限制。','只检查元素集合；忽略中间被压住的元素；把所有递归转迭代都当成必须显式栈。','能给操作序列或首次冲突位置；高分能由非法模式说明不可能，并推条件计数。','常规；2026限制首项计数和231模式推导为较难。',[
('可达性与操作模拟','序列|排列|Push|Pop|容量|队列','模拟入栈出栈；递增输入不允许i<j<k且Pk<Pi<Pj的231模式。'),
('条件计数','计数|取值个数|Catalan','总数C_n=sum(C_i C_(n−1−i))；首项固定1为C_(n−1)，首项2有两种后续分支，逐分支计数不重复。'),
('调用栈与括号深度','递归|调用|括号','调用按进入压栈、返回出栈；括号容量由未匹配左括号峰值决定。')])
add('DS06','算法与线性结构','先进先出、模运算、链表','循环队列指针、受限双端队列、多轨道重排与扩容设计。','先写front/rear各指向什么，再推空满条件；预留一格模型常用(rear+1)%N=front判满，但指针定义变化时必须重新推。','死背队空队满式；把输出受限与输入受限混淆；动态队列释放空间违反只增不减要求。','能画初态、首次入队和满队扩容；高分能给保持O(1)入出队的不变量。','常规到综合；动态循环链队列与最少轨道数需要结构设计。',[
('FIFO与受限双端模拟','先进先出|双端|直接输出|轨道|FIFO','逐次检查允许操作的端点；多FIFO轨道内顺序不可逆，按递增子序列划分。'),
('循环队列空满','front|rear|循环队列|队空队满|初态|首个元素','根据题设“指当前元素”或“下一位置”推初始值，模N处理回绕。'),
('可扩容循环链队列','空间只增|循环链|备用|增结点|复用','预留空闲结点，队满时在边界插入新结点；出队移动指针保留存储。')])
add('DS07','算法与线性结构','栈、运算优先级、二叉树','中后缀转换、两栈求值、括号匹配与表达式树输出。','操作数直接输出；操作符按优先级和结合性弹栈，括号不输出。求值先弹右操作数再弹左操作数。表达式树按递归结构加足够括号保语义。','把减除的左右操作数反置；漏同级左结合；用根最先计算误解表达式树。','能给每步栈状态、后缀式和求值；高分可将表达式树带一元运算也正确输出。','常规；树转表达式含根与叶的括号例外为综合。',[
('转换与求值','中缀|后缀|操作数栈|运算符栈|左结合','对括号、优先级、结合性逐次处理，记录指定扫描时刻栈内容。'),
('括号和表达式树','括号|表达式树|根运算|一元','匹配括号看峰值深度；树递归输出对非叶非根加括号，不能丢一元操作符。')])
add('DS08','算法与线性结构','下标、等差求和、字节地址','二维数组、三角／三对角压缩、稀疏矩阵及跨存储层地址计算。','先统一0基或1基。行优先偏移=((i−行下界)×列数+j−列下界)×元素字节数；压缩数组先数完整行／列，再数当前段。','矩阵1基与数组0基混用；对称矩阵未交换坐标；稀疏三元组丢总行列数；把元素偏移当字节偏移。','能从存储次序重新推公式而非混背；高分能继续分解页号和Cache字段。','常规；跨页、压缩与未知列数反推属于综合。',[
('常规二维地址与跨层计算','二维|数组|行优先|页数|页故障|Cache|下标地址','先算字节地址，再交OS10或CO10分解；占用块数用首末地址而非只除总大小。'),
('特殊矩阵压缩','三角|三对角|对称','用前面各行／列元素数累加，边界行单独检查。'),
('稀疏结构','稀疏|三元组','三元组含行、列、值，另存矩阵总行列与非零数；十字链表保留按行按列访问。')])
add('DS10','树与图','边数双重计数、树高约定','树结点数量、完全树位置、正则k叉树和顺序存储合法性。','树边数n−1等于各结点度数之和。二叉树n0=n2+1；完全树按层填满后处理末层。顺序存储检查每个非空位置的祖先。','把满树、完全树和正则树混同；高度按边数或层数混用；结点数等于数组最大下标。','能推叶数、最少／最多结点和存储长度；高分构造达到上下界的树。','常规；正则树极值与森林高度优化为较难。',[
('数量与高度上下界','结点数|总结点|总节点|叶与分支数|叶数|叶结点|树数|Catalan|三叉|正则|高度','用边数恒等式和各层容量；树高先明确根为第1层，构造极端树验证。'),
('顺序存储边界','顺序存储|索引|非空结点','1基孩子2i、2i+1；空位不压缩，祖先为空则后代不能非空。'),
('森林高度最小化','森林树序','每棵转换后根无右孩子，子树最小高度受容量限制；按贡献高度从大到小排列以减少后移代价。')])
add('DS11','树与图','递归、根左右的遍历定义','遍历序列、重建、线索及携带深度的树算法。','先确定根，再用中序划分左右子树，分别过滤其他遍历序列递归。线索仅占原空指针，指向对应遍历的相邻结点。','前后序通常不能唯一重建；只判局部父子代替BST全局约束；WPL根深度应为0。','能给重建过程并回代全部已知序列；高分用统一递归框架处理WPL和表达式输出。','常规到综合；不唯一性、森林对应及算法输出条件需联合推理。',[
('重建与遍历关系','遍历|先序|前序|后序|中序|先中序|层序|树形|重建','有中序时划左右；前后序相反只能推出单支形态，左右仍可能不确定。'),
('线索与前驱后继','线索|前驱|后继','先写遍历序列再填空指针；有两孩子结点的中序前驱是左子树最右结点，后继对称。'),
('遍历算法应用','WPL|weight|深度|表达式|BST|索引|一元操作符','WPL只累加叶权×深度；判BST保持前值或上下界；输出表达式保结构括号。')])
add('DS12','树与图','一般树、二叉树遍历','左孩子右兄弟转换、树数叶数关系及高度优化。','左指针连第一个孩子、右指针连下一个兄弟；森林根沿二叉树根的右链连接。一般树先根对应二叉先序，后根对应二叉中序。','把右孩子当原树孩子；把二叉树无右孩子直接等同原树叶；忽视树序可调整。','能双向还原亲属关系与遍历；高分推树数和最小高度。','常规；2026高度优化为较难，需同时优化各树形状与排列。',[
('结构数量与遍历对应','.*','原树叶对应无左孩子；森林树数为根右链长度；给树大小而未给形状时不能固定成链。'),
('可换树序的高度','树序','n结点一般树转为根无右孩子的二叉树，最小高度为1+ceil(log2 n)（n=1亦成立）；较高者放前，比较h_i+i−1。')])
add('DS13','树与图','权值、路径长度、贪心合并','哈夫曼构造、前缀码、译码、最优合并及三叉／k叉补零。','二叉每次取最小两权合并；WPL可用叶权×深度和或内部合并权之和交叉验证。码字放根叶路径，译码遇叶输出并回根。','误以为最优树唯一或一定完全；有相同权时码字可不同；平均码长未除总频数；前缀冲突和重复码字漏判。','能构造、编码、译码并校验WPL；高分能论证合并代价并处理非二叉。','常规；多叉补零、动态前缀码插入与最优合并为综合。',[
('二叉构造和性质','哈夫曼|WPL|码长|度为1|权值序列|最小权|同深度|字符数','合并权相等时保留等价选择；结点2n−1和无度1结点只用于二叉满结构。'),
('前缀判定与编译码','前缀|译码|编码树|码字|比特串','插入途经已有叶或终点已有后代均冲突；完整码字不能是另一字的前缀。'),
('最优合并','合并|归并','二路合并最坏比较m+n−1，所有合并减去的常数固定，仍按最小权优先。'),
('多叉补零','三叉|k路|虚叶|虚段','补最少零权使(n−1)整除(k−1)，再每次合并k项；不能用二叉树结点公式。')])
add('DS14','树与图','全局有序区间、递归','BST查找路径、插删、验证、加权查找组织与最接近值。','每次向左缩小上界、向右提高下界；验证时传递全部祖先边界或检查中序严格递增。最近值沿搜索路径更新前驱后继；差值用足够宽类型。','只比较父子；删后重插必恢复树形；将等距离候选漏掉；不明确重复关键字约定。','能写完整BST验证与最近值算法；高分解释候选为何只需路径上的边界值。','常规到综合；加权查找优化和输出全部最近值为较难。',[
('区间和插删路径','路径|删除|插入|取值|大小关系|反向BST|祖先','标准BST保持左小右大；题设反向时全部不等号同步反向；叶删除重插与非叶分开。'),
('验证整棵BST','判BST|递归上下界|父子|空结点','中序序列严格递增是互异关键字BST的充要条件；跳过空位置不等于跳过其合法性检查。'),
('加权查找结构','概率|加权|查找组织|链式','ASL=sum(p_i×比较层数)；比较按概率顺排和合法BST结构，不能只按结点数评价。'),
('最近值及并列','最接近|最近|差值|候选','沿与k比较的查找路径更新距离，保留两侧等距值；常规严格BST至多两个不同最近键，允许重复时另核题意。')])
add('DS15','树与图','BST、子树高度','AVL判断、插入删除旋转及给高度求数量界。','逐结点计算左右高差；插入从下向上找首个失衡祖先，按LL/RR/LR/RL旋转。最少结点N(h)=1+N(h−1)+N(h−2)，N(0)=0,N(1)=1。','只看根平衡；旋转后破坏中序；误以为删除叶再插回总恢复。','能画每次旋转和高度；高分把最满子树与合法最少子树组合求极差。','常规；高度约束极值和删除反例为综合。',[('旋转与平衡辨析','旋转|插入|删除|平衡|图示|反向','旋转保持中序，不保持原树形；反向BST可对称处理。'),('高度和数量极值','高度|递推|结点数最大差','一侧高h−1另一侧至少h−2，分别取满树和最少AVL再比较，不能任意配高差超过1的子树。')])
add('DS16','树与图','多路查找、根的例外约束','B树阶、关键字／孩子数量、插删借并、结构枚举和高度界。','m阶非根内部结点孩子数在ceil(m/2)…m，关键字少1；根非叶至少2孩子。插入先定位叶层，溢出分裂提升；删除内部键先替代，再借或并。','B树叶结点口径含不含失败外结点要看题；新键可能经提升进入内部；成功查找未必到叶。','能列每层最少最多容量并画所有满足条件的操作结果；高分枚举不能漏不同借并选择。','常规到较难；内部删除和给关键字总数枚举结构最易漏解。',[
('结构容量与B+辨析','阶|高度|最少|最大数|共有|关键字总数|结构数量|叶层','统一树高和叶结点口径后用根例外与各层最少分支计数；枚举按根关键字数分支。'),
('插入分裂','插入|分裂|提升','满结点分裂提升中间键，可能向上递归且根高度增加；保持全部叶同层。'),
('删除借并','删除|前驱|后继|借|合并','可用前驱或后继替代；兄弟有富余借，否则经父键合并，检查父结点是否继续下溢。')])
add('DS17','树与图','B树、索引与顺序访问','B+树数据位置、叶链和数据库索引适用性。','内部结点充当索引，数据记录集中在叶层；单点检索沿根叶路径，区间／顺序扫描再走叶链。','把B树成功可停内部套到B+；认为有叶链就不需索引检索。','能对比两树的记录位置、查找终点和有序扫描能力。','基础到常规；选项中共有性质和特有性质需分开。',[('B树与B+检索差异','.*','仅把叶链、有序扫描和记录集中叶层作为B+特征，按题给阶的定义计结点容量。')])
add('DS18','树与图','顶点边、连通、度、路径','图的数量约束、反例、DAG表达式、欧拉路径和有环语言。','无向度和=2E，有向出度和=入度和=E；先辨简单图、连通与方向，再用极端构造验证命题。已知无向图连通时欧拉路要求奇度点0或2。','E≥V−1不是连通充分条件；矩阵幂描述游走不保证简单路径；DAG不等于拓扑序唯一。','能给出等式与最小反例；高分将实际描述化图并说明条件不可删。','常规；图性质的充要性及路径语言的环结构是综合。',[
('度数边数与连通界','度|边数|最少顶点|连通|欧拉|K顶点','由度和守恒推界，保证连通用最大不连通图反推；欧拉结论须保留连通条件。'),
('图建模与路径性质','路径|回路|拓扑|DAG|表达式|网络抽象|带字符|有环','共享相同子表达式可合并DAG结点；有可达环且能到终点才产生任意长游走，原题的可达前提不能丢。')])
add('DS19','树与图','二维数组、链表、边方向','矩阵、邻接表、多重表、矩阵幂及图算法实现成本。','矩阵行统计出度、列统计入度；无向边两端各贡献1。邻接表只存出边时求所有入度要扫描全部边。矩阵幂按乘法展开解释长度固定的游走。','链表访问方向错；无向边计一次度；把A^k非零断言为无重复顶点的路径。','能从原图构造结构并反向还原；能写度数扫描代码及O(V²)/O(V+E)依据。','常规到综合；多重表字段切换与矩阵幂语义需要细辨。',[
('结构互换和扫描','矩阵|邻接表|多重表|字段|存储|入度|出度|度数|奇度|K顶点','按端点决定沿哪条边链继续；无边哨兵与权0必须按原题区分。'),
('矩阵幂与游走','平方|矩阵幂|两步','(A²)ij=sum(Aik Akj)枚举中间点；一般A^k计长度k的游走，可重复顶点。')])
add('DS20','树与图','栈队列、访问标记','DFS/BFS序列、遍历复杂度、逆拓扑及等权最短路。','DFS沿未访问邻点深入到底再回溯；BFS入队即标记，按层扫描。序列唯一性取决于邻接访问次序。','把MST当BFS最短路树；BFS用于一般不等权路径；DFS退出序列正反弄错。','能模拟并指出非法序列首次违反约束的位置；高分给不同存储结构下复杂度。','常规；邻接次序枚举与DFS逆拓扑的条件为综合。',[('遍历模拟与成本','.*','邻接表O(V+E)、矩阵O(V²)；DAG中DFS退出顺序为逆拓扑；无权或等正权图BFS给最少边路径。')])
add('DS21','树与图','连通无向带权图、割与环','Prim/Kruskal、等权分支、MST唯一性及组网后路径。','Prim每次选已选集合到外部最轻边；Kruskal全图按权排序，仅加入不成环边。结束检查V−1条边与连通性。','MST总权最小不代表根到各点最短；最小边可能有等价替代；不同边权是唯一性充分而非必要条件。','能模拟两算法并枚举等权选择；高分用非树边与树上路径最大边比较验证唯一性。','常规；枚举全部MST和唯一性必要充分边界为较难。',[
('选边与存储适配','Prim|Kruskal|跨割|选边|存储结构','稠密图矩阵Prim自然；稀疏边集Kruskal自然。第二条边受当前已选集合约束。'),
('等权与唯一性','唯一|等权|最小边|枚举','对某棵MST，每条非树边权若严格大于其树上连接路径最大边则唯一；相等可交换成另一MST。'),
('路径及网络交叉','最短路|组网|TTL','在选出的树上另数路径边／路由器，不用总权替代跳数；TTL问题交NET13。')])
add('DS22','树与图','非负边权、松弛','Dijkstra中间状态、路由代价与错误贪心反例。','dist存从源到未定点的当前最短估计；每次从全部未定点选dist最小者，再松弛其出边，记录前驱。','从当前点选最近邻并不等于全局最小dist；未确定点的估计不一定最终正确；MST不代替最短路。','能逐轮写已定集合、dist和前驱；高分构造三四点反例并说明正确贪心的不变量。','常规到综合；反例设计和指定时刻数组状态更难。',[('Dijkstra与反例','.*','算法条件为非负边；等权无向图可用BFS，错误最近邻算法用绕行更短的路径推翻。')])
add('DS23','树与图','入度、DAG、偏序','拓扑合法性、数量、唯一性、判环和逆拓扑。','不断取零入度点，删除其出边并更新入度。无候选但尚有顶点是环；每轮恰一个候选且全部处理，才是唯一拓扑序。','一次出现零入度点不证明无环；固定某种队列顺序所得一条序列不证明唯一。','能枚举分支而不重漏，能实现唯一性判定；高分说明矩阵与表的复杂度差异。','常规；唯一性算法设计和序列计数为综合。',[('拓扑排序与条件分支','.*','给定序列逐边验证前后关系；计数在每轮可选点处分叉，回溯恢复入度；DAG的DFS退出序取反得到拓扑序。')])
add('DS24','树与图','拓扑顺序、最长路径','AOE工期、关键活动、余量、活动重叠与延期补偿。','正向ve(v)=max(ve(u)+w)，逆向vl(u)=min(vl(v)−w)。活动e=ve(u)，l=vl(v)−w，余量l−e；关键活动余量0。','把关键路径当最短路；缩短一条关键路径不一定缩工期；事件时间和活动时间混用。','能完整列ve/vl和活动表；高分在改变某活动时重算受影响后继及全部关键路径。','常规到较难；多关键路径压缩与固定延期后的补偿需全图推理。',[
('工期与余量','.*','按拓扑正反两遍算，项目有多个终点时用公共终点或统一工期处理。'),
('延期压缩与并行活动','同时|压缩|延后|延迟|补偿|缩短','同时可执行需满足依赖和可行时间区间，不能仅看不是同一路径；缩工期需覆盖所有制约的关键路径。')])
add('DS25','查找与排序','概率加权、比较次数','顺序查找、跳步、均匀分块及非等概率优化。','ASL=sum(p_i c_i)。等概率且索引块内均顺查时ASL约(块数+块长)/2+1，在块数×块长=n约束下两者近sqrt(n)最优。','把折半查找总当加权ASL最优；索引改折半后仍套sqrt(n)；目标靠前时跳步未必更好。','能逐元素列比较数并按概率加权；高分比较不同合法结构且保留顺序与链式限制。','常规；非等概率结构设计为较难。',[('查找组织与加权优化','.*','按给定成功概率选择结构；顺序表可按概率降序顺查，链式结构可构造更优加权BST；不要求扩展通用最优BST动态规划。')])
add('DS26','查找与排序','有序顺序表、区间边界','折半判定树、失败／成功比较、路径验证及中位数折半。','明确上下界闭开及中点向下／向上取整；每次排除已比较中点及不可能半区。n>0时最坏关键字比较floor(log2 n)+1。','链表有序不等于随机访问；失败外结点不额外做一次关键字比较；平均次数与最大次数混用。','能画判定树并回代查找路径；高分将有序性用于等量排除但说明奇偶边界。','常规；判定树形态约束与双序列中位数为综合。',[('标准折半与判定树','.*','标准公式仅用于约定的折半查找，不把代码中多个布尔判断当多个关键字比较。'),('双序列中位数','中位数|等量排除','与DS03交叉；删除两端数量必须相同，保留目标秩。')])
add('DS27','查找与排序','取模、数组、标记','散列构表、冲突、装填因子、成功失败ASL、删除与直接定址标记。','按原散列函数和探测式逐个插入。成功成本从各键初始地址追到实际位置；失败成本从每个可能初始地址追到首个真正空槽，再按概率平均。','表长不等于散列函数值域；删除标记不是空槽；平方探测不保证遍历全表；无冲突不等于装填因子小即可保证。','能复现完整探测链；高分解释同义／非同义冲突及失效的删除方式。','常规；删除后的失败ASL和值域不等于表长是综合。',[
('装填冲突与线性探测','装填|线性|聚集|散列函数|冲突|查找效率','α=元素数/表长，线性探测依次模表长移动；ASL还受函数和聚集影响。'),
('成功失败及删除','ASL|失败|删除|比较序列|空槽','终止于真正空槽，删除槽继续探测；分母用题目规定的初始地址分布。'),
('平方探测','平方','严格按题给H0+k²而非自行换±k²，记录循环和空槽。'),
('有界直接定址','标记|缺失|去重','DS03/DS04中的标记数组是必要的直接定址思想，不把它伪装成有冲突散列统计；对应角色记前置。')])
add('DS28','查找与排序','稳定性、比较与移动的区别','排序选择、过程识别、稳定性及比较计数排序。','识别每一趟保持的不变量：有序前缀、固定极值、枢轴分区或成倍有序段。稳定性用相同键的原始先后作反例检查。','把比较次数少等同移动次数少；只看最终有序结果鉴别算法；比较计数排序不是按值域桶计数排序。','能用带身份的重复关键字检验稳定性，解释时间空间与存储结构适配。','常规；自定义比较计数算法的稳定性修正为综合。',[
('过程和性能辨析','中间|每趟|识别|时间|存储|移动|选择考虑|性质|不稳定|比较次数','对每个候选算法用不变量排除，列最坏时间、辅助空间和稳定条件。'),
('比较计数排序','比较计数|相等元素|生成输出|双循环','成对比较给较大者排名加1；相等时需给后出现者加1以保持稳定且避免同排名覆盖。'),
('多关键字排序','多关键字|先次后主','先次要后主要排序，后续每趟稳定；完全并列还要保留原始次序。')])
add('DS29','查找与排序','有序前缀、逆序对','直接／折半插入的比较与移动、近有序选择。','第i趟将当前项插入前i−1项有序区；移动等于越过的较大元素数。折半只减少定位比较，不减少数组移动。','漏记停止比较；把哨兵比较计入或排除未统一；近有序改进不代表任何指标均优于选择排序。','能逐趟统计并说明是否计哨兵；高分比较初始顺序对两种成本的不同影响。','常规；精确比较次数的终止边界需细心。',[('插入过程与性能','.*','保持相等元素相对次序时插在已有相等项之后；希尔的每个增量子序列用相同插入机制。')])
add('DS30','查找与排序','直接插入、下标同余','按中间状态反推希尔增量及子序列排序。','给定增量d，将下标模d相同的元素各自插排；检查每个子序列有序而非要求整体有序。','把连续d项当一组；某趟局部有序不说明稳定；只检查一个同余类。','能按候选增量逐组验证并模拟一趟；高分从多趟状态联立排除。','常规；中间状态可能兼容多个增量，应验证全部给定轮次。',[('增量子序列','.*','一趟d排序后所有距离d的序列有序；后续增量减小到1完成排序。')])
add('DS31','查找与排序','相邻交换','冒泡方向、中间状态与极值就位。','按题给扫描方向逐对比较交换，每趟使一端极值就位；若一趟无交换可提前终止。','把插入的有序前缀与冒泡固定后缀混同；未注明从左到右或从右到左。','能根据连续两趟状态定位扫描方向并验证每次交换。','常规；重点是中间状态不变量。',[('逐趟模拟与鉴别','.*','先验证极值最终位置，再重放相邻交换，不只凭局部有序猜算法。')])
add('DS32','查找与排序','枢轴分区、目标秩','快排中间结果、递归划分和快速选择。','一趟划分只保证枢轴两侧范围关系。排序递归两边，选择仅递归含目标秩的一边。检查重复键和枢轴规则。','认为两边分别有序或数量一定平衡；把平均O(n)选择写成最坏O(n)；把递归次序当树结构变化。','能验证枢轴位置并实现迭代选择；高分说明最坏退化与固定k堆的取舍。','常规到综合；设计选择算法及复杂度条件更难。',[
('快排分区不变量','快排|快速排序|枢轴|分区|第二趟|一次划分','每个已就位枢轴都满足左不大于右不小于；具体等号处理依题实现。'),
('顺序统计与小k','子集|半区|快速选择|最小10|固定大小|固定k|原地划分','只定位目标秩，不全排序；固定大小大根堆保存最小k个，时间O(n log k)、空间O(k)。'),
('算法选择辨析','近有序','近有序小规模且要求稳定时直接插入更贴切；普通快排不稳定且固定枢轴可退化，最坏时间和移动可达平方量级。快排划分不等于归并有序段，也不直接构成外存多路归并路线。')])
add('DS33','查找与排序','选择极值、比较移动','简单选择的过程与最坏移动次数。','每趟扫描未排序区选最小，与首位交换。关键字比较固定n(n−1)/2，交换至多n−1次；元素赋值次数按一次交换的实现计。','把O(n)移动说成O(n)总时间；相等元素远距离交换可能破坏稳定。','能比较插入与选择在近有序输入上的不同成本。','基础到常规；区分移动和比较是关键。',[('选择过程和成本','.*','不因数据已有序而省去标准选择扫描；固定位置是每趟不变量。')])
add('DS34','查找与排序','完全二叉树、数组下标','堆的建立、插入、删除、比较次数与小k筛选。','插入放末尾向上比较；删根以末项补根后选较优孩子下滤；自底向上从最后非叶开始建堆。','堆不是BST；逐个插入与自底向上可能得不同合法堆；漏孩子间比较；删根后忘缩堆长。','能画每步数组并分别数父子、孩子比较；高分用大根堆维护最小k个。','常规；精确比较和两种建堆路径为综合。',[('堆结构与调整','.*','0基孩子2i+1、2i+2；1基孩子2i、2i+1。自底向上建堆O(n)，不能按每项logn简单定为紧界。')])
add('DS35','查找与排序','两个有序序列、双指针','二路归并、中间段、实际比较与最优合并顺序。','两指针比较当前头项，小者输出；一边耗尽后直接复制剩余，不再做关键字比较。最坏m+n−1，实际可能更少。','无条件套最坏次数；把归并叫快速划分；等键先取右侧导致不稳定。','能逐次列比较并追踪各有序段长度；高分用哈夫曼式顺序降低总最坏代价。','常规；不等长多表最优合并为综合。',[('归并机制与实际成本','.*','数组归并需辅助存储；链式可改链；指定合并顺序必须服从，未指定最优才选择短表先合。')])
add('DS36','查找与排序','稳定分配收集、位权','LSD基数排序和多关键字稳定排序。','从最低优先级字段开始，每趟稳定分配到桶再按桶序收集，已有次序作为相等时的次级约束。','高位先处理却仍套LSD结论；桶内反向收集；忽略稳定性和负数编码前提。','能写每趟完整序列，解释为什么主要关键字最后处理。','常规；完全并列保序与多字段组合需细辨。',[('稳定分配收集','.*','题给十进制或字段顺序决定趟数；移动次数主要随位数和元素数变化，不依初始排列。')])
add('DS37','查找与排序','归并、外存I/O、最优树','外部归并、置换选择、败者树、归并趟数与多叉最优合并。','先形成初始有序段，再k路归并。规则段数r且每轮最多合k段时趟数ceil(log_k r)。实际总I/O还取决于每趟读写和段长度。','把内存容量当置换选择段长上限；平均约2m不是确定值；败者树冠军处存的是段号而非必然直接存键。','能模拟冻结与新段启动，计算趟数并说明边界；高分构造补零的最优归并树。','综合；置换选择冻结和多叉补段为较难。',[
('外排序与趟数','超内存|外部|趟数|初始段','先明确初始段数量再求归并轮数，增加k可能降低轮数但不改变所有成本。'),
('置换选择','置换|冻结|首段|内存','输出当前最小合格键，新读键若小于上次输出则冻结；全部冻结后开启新段。首段最短m、最长n。'),
('败者树','败者树|冠军','内部比较保存败者，冠军对应当前全局最小键所在段，更新只沿其路径。'),
('最优多路归并','最优|虚段','补零满足满k叉条件，反复合并最短k段；代价为每段长度×参与合并层数。')])
add('DS39','查找与排序','字符串前后缀、下标约定','KMP失配回退、next/nextval、实际比较和最大滑移。','先声明0基或1基及next定义；失配时主串位置不退，模式位置转next[j]；nextval跳过下一次必定同字符失配的位置。','混用next版本；把滑动长度当next值；模式回退误计成主串重新比较全部。','能构造数组并逐次记录字符比较；高分说明最大滑移来自哪个失配位置。','常规到综合；nextval与计数口径最易出错。',[('失配跳转与比较','.*','按统一索引约定模拟，匹配成功终止；仅实际执行字符相等测试时增加比较数。')])
